import{_ as e,o as l,c as i,a3 as t}from"./chunks/framework.DjfA6S92.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"team/Stages.md","filePath":"team/Stages.md"}'),r={name:"team/Stages.md"};function o(h,a,n,s,d,u){return l(),i("div",null,[...a[0]||(a[0]=[t('<h2 id="q-工程师的阶段是怎样的-不同阶段应该具备怎样的技能" tabindex="-1">Q: 工程师的阶段是怎样的？不同阶段应该具备怎样的技能？ <a class="header-anchor" href="#q-工程师的阶段是怎样的-不同阶段应该具备怎样的技能" aria-label="Permalink to &quot;Q: 工程师的阶段是怎样的？不同阶段应该具备怎样的技能？&quot;">​</a></h2><h2 id="a" tabindex="-1">A: <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A:&quot;">​</a></h2><p><code>Author: @liyuk @bailnl @sys</code></p><p>工程师对应职级的一个粗浅界定：</p><h3 id="初级" tabindex="-1">初级 <a class="header-anchor" href="#初级" aria-label="Permalink to &quot;初级&quot;">​</a></h3><ul><li>知道一些基本的概念</li><li>并且对这些概念有所实践</li><li>能够独立的解决一些问题。</li></ul><hr><h3 id="中级" tabindex="-1">中级 <a class="header-anchor" href="#中级" aria-label="Permalink to &quot;中级&quot;">​</a></h3><ul><li>对于计算机基础有全面的认知和系统性的学习</li><li>对于软件开发的整个流程，包括整体架构、工程化、自动化有深刻理解</li><li>全面了解关于所使用的技术的各个方面的基础内容</li><li>有针对技术上的某个点进行过深入的了解</li><li>有良好的编程思维，以及比较好的代码习惯</li><li>能够独立的解决绝大部分问题</li><li>思考能力强，有潜力。</li></ul><hr><h3 id="高级" tabindex="-1">高级 <a class="header-anchor" href="#高级" aria-label="Permalink to &quot;高级&quot;">​</a></h3><ul><li>能够判断未来两年的技术发展趋势</li><li>作为技术人员配合多部门完成市场目标</li><li>优化软件供应链，分清楚个人的角色和定位</li></ul><h4 id="路径" tabindex="-1">路径 <a class="header-anchor" href="#路径" aria-label="Permalink to &quot;路径&quot;">​</a></h4><ul><li>全面地、系统地学习基础知识，实现完整的知识体系</li><li>找到痛点做有价值的事情，突破成为某个方向的专家</li></ul><h4 id="核心" tabindex="-1">核心 <a class="header-anchor" href="#核心" aria-label="Permalink to &quot;核心&quot;">​</a></h4><ul><li>对于技术的热情，对于突破某个点的渴望</li></ul><hr><h3 id="资深" tabindex="-1">资深 <a class="header-anchor" href="#资深" aria-label="Permalink to &quot;资深&quot;">​</a></h3><p>暂不在认知范畴之内了，如果需要了解看看扩展阅读。</p><h2 id="roast" tabindex="-1">Roast: <a class="header-anchor" href="#roast" aria-label="Permalink to &quot;Roast:&quot;">​</a></h2><p>拓展阅读：<a href="https://zhuanlan.zhihu.com/p/20156540" target="_blank" rel="noreferrer">工程师你为啥升不上去</a></p><p>有句话说得很好“职位并非越高越好，升职也未必是越快越好，一定要和能力相匹配。”</p><p><strong>谨记莫要成为<code>南郭先生</code>。</strong></p><p>这个分类更多的是个人主观的分类，如果觉得有不对的地方，欢迎直接pr或者issue。</p>',24)])])}const m=e(r,[["render",o]]);export{p as __pageData,m as default};
